package com.benjamintaskis.createsignalextensions.network; import com.benjamintaskis.createsignalextensions.CreateSignallingAdditions; import net.minecraft.core.BlockPos; import net.minecraft.network.RegistryFriendlyByteBuf; import net.minecraft.network.codec.StreamCodec; import net.minecraft.network.protocol.common.custom.CustomPacketPayload; public record SetSignalPlateTextPayload(BlockPos pos,String text) implements CustomPacketPayload { public static final Type<SetSignalPlateTextPayload> TYPE=new Type<>(CreateSignallingAdditions.id("set_signal_plate_text")); public static final StreamCodec<RegistryFriendlyByteBuf,SetSignalPlateTextPayload> STREAM_CODEC=StreamCodec.ofMember(SetSignalPlateTextPayload::encode,SetSignalPlateTextPayload::new); public SetSignalPlateTextPayload(RegistryFriendlyByteBuf b){this(b.readBlockPos(),b.readUtf(32));} private void encode(RegistryFriendlyByteBuf b){b.writeBlockPos(pos);b.writeUtf(text,32);} public Type<? extends CustomPacketPayload> type(){return TYPE;} }